package main
import("bufio";"crypto/sha256";_ "embed";"encoding/binary";"encoding/hex";"encoding/json";"errors";"fmt";"io";"os";"os/exec";"runtime";"strings";"sync";"time")
//go:embed native/qos-observer
var qosObserver []byte
const diagSubscriptionPath="/data/airlink/subscription.json"
type DiagSubscription struct{QCI int `json:"qci"`;Down uint64 `json:"down_kbps"`;Up uint64 `json:"up_kbps"`;APN string `json:"apn"`;Bearer int `json:"bearer_id"`;CapturedAt int64 `json:"captured_at"`;Boot string `json:"boot"`;SIM string `json:"sim_fingerprint"`}
var diagSubMu sync.Mutex
var diagSub DiagSubscription
func ambrKbps(base,ext,ext2 byte)(uint64,bool){var n uint64;switch{case base==0:return 0,false;case base==255:n=0;case base<=63:n=uint64(base);case base<=127:n=64+uint64(base-64)*8;default:n=576+uint64(base-128)*64};if ext>0{switch{case ext<=74:n=8600+uint64(ext)*100;case ext<=186:n=16000+uint64(ext-74)*1000;case ext<=250:n=128000+uint64(ext-186)*2000;default:return 0,false}};if ext2>0{switch{case ext2<=61:n=256000+uint64(ext2)*4000;case ext2<=161:n=500000+uint64(ext2-61)*10000;case ext2<=246:n=1500000+uint64(ext2-161)*100000;default:return 0,false}};return n,true}
func decodeAPN(b []byte)(string,error){var labels []string;for at:=0;at<len(b);{n:=int(b[at]);at++;if n==0||n>63||at+n>len(b){return "",errors.New("APN 格式错误")};v:=b[at:at+n];for _,c:=range v{if !(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='-'){return "",errors.New("APN 字符错误")}};labels=append(labels,string(v));at+=n};if len(labels)==0{return "",errors.New("APN 为空")};return strings.ToLower(strings.Join(labels,".")),nil}
func parseESMSubscription(b []byte)(DiagSubscription,error){var d DiagSubscription;if len(b)<3||b[0]&15!=2||b[2]!=0xc1{return d,errors.New("不是默认承载建立消息")};d.Bearer=int(b[0]>>4);if d.Bearer<5||d.Bearer>15{return d,errors.New("承载 ID 无效")};at:=3;lv:=func()([]byte,error){if at>=len(b){return nil,io.ErrUnexpectedEOF};n:=int(b[at]);at++;if n<1||at+n>len(b){return nil,io.ErrUnexpectedEOF};v:=b[at:at+n];at+=n;return v,nil};q,e:=lv();if e!=nil{return d,e};d.QCI=int(q[0]);if d.QCI<1{return d,errors.New("QCI 无效")};apn,e:=lv();if e!=nil{return d,e};d.APN,e=decodeAPN(apn);if e!=nil{return d,e};first:=strings.Split(d.APN,".")[0];if first=="ims"||first=="sos"||first=="emergency"||d.QCI==5{return d,errors.New("不是互联网默认承载")};if _,e=lv();e!=nil{return d,e};found:=false
 for at<len(b){tag:=b[at];at++;if tag>=0x80{continue};if tag==0x32||tag==0x58{if at>=len(b){return d,io.ErrUnexpectedEOF};at++;continue};n:=0;if tag==0x7b{if at+2>len(b){return d,io.ErrUnexpectedEOF};n=int(binary.BigEndian.Uint16(b[at:]));at+=2}else{if at>=len(b){return d,io.ErrUnexpectedEOF};n=int(b[at]);at++};if at+n>len(b){return d,io.ErrUnexpectedEOF};v:=b[at:at+n];at+=n
 if tag==0x5e{if n!=2&&n!=4&&n!=6{return d,errors.New("AMBR 长度错误")};var dx,ux,dx2,ux2 byte;if n>=4{dx,ux=v[2],v[3]};if n==6{dx2,ux2=v[4],v[5]};down,ok:=ambrKbps(v[0],dx,dx2);up,ok2:=ambrKbps(v[1],ux,ux2);if !ok||!ok2{return d,errors.New("AMBR 编码未支持")};d.Down,d.Up=down,up;found=true}
 if tag==0x5f{if n!=6{return d,errors.New("扩展 AMBR 长度错误")};unit:=func(v byte)(uint64,bool){units:=[]uint64{0,200,1000,4000,16000,64000,256000,1000000,4000000,16000000,64000000,256000000,1000000000,4000000000,16000000000,64000000000,256000000000,1000000000000,4000000000000,16000000000000,64000000000000,256000000000000};if int(v)>=len(units)||v<3{return 0,false};return units[v],true};du,ok:=unit(v[0]);uu,ok2:=unit(v[3]);if !ok||!ok2{return d,errors.New("扩展 AMBR 单位未支持")};d.Down=du*uint64(binary.BigEndian.Uint16(v[1:3]));d.Up=uu*uint64(binary.BigEndian.Uint16(v[4:6]));found=true}
 };if !found{return d,errors.New("消息没有返回 AMBR")};return d,nil}
func parseDiagSubscriptionLine(line string)(DiagSubscription,error){f:=strings.Fields(line);if len(f)==2&&f[0]=="ESM"{b,e:=hex.DecodeString(f[1]);if e!=nil{return DiagSubscription{},e};return parseESMSubscription(b)};if len(f)==3&&f[0]=="LOG"&&f[1]=="b0e2"{b,e:=hex.DecodeString(f[2]);if e!=nil||len(b)<19||int(binary.LittleEndian.Uint16(b))!=len(b)||b[2]!=0xe2||b[3]!=0xb0||b[12]!=1{return DiagSubscription{},errors.New("诊断帧错误")};return parseESMSubscription(b[16:])};return DiagSubscription{},errors.New("非目标日志")}
func subscriptionIdentity()(string,string){b,_:=os.ReadFile("/proc/sys/kernel/random/boot_id");boot:=strings.TrimSpace(string(b));id:=nv("iccid");if len(id)<18{raw,e:=cmd("ubus","call","qmi_svr","get_iccid","{}");if e==nil{var value struct{ICCID string `json:"iccid"`};if json.Unmarshal([]byte(raw),&value)==nil{id=strings.TrimSpace(value.ICCID)}}};if len(id)<18||len(id)>22{return boot,""};id=strings.ToUpper(id);for _,c:=range id{if !(c>='0'&&c<='9'||c>='A'&&c<='F'){return boot,""}};hash:=sha256.Sum256([]byte(boot+":"+id));return boot,hex.EncodeToString(hash[:])}
func diagResult(d DiagSubscription)map[string]any{return map[string]any{"available":true,"qci":d.QCI,"down_kbps":d.Down,"up_kbps":d.Up,"apn":d.APN,"bearer_id":d.Bearer,"captured_at":d.CapturedAt,"source":"DIAG NAS · 默认承载","response_state":"available","message":"网络最近一次下发的 APN-AMBR / QCI；属于承载上限，不是实测网速。"}}
func storeDiagSubscription(d DiagSubscription,at int64)error{d.Boot,d.SIM=subscriptionIdentity();if d.Boot==""{return errors.New("无法识别当前开机会话")};d.CapturedAt=at;diagSubMu.Lock();diagSub=d;raw,e:=json.Marshal(d);if e==nil{e=os.WriteFile(diagSubscriptionPath+".tmp",raw,0600);if e==nil{e=os.Rename(diagSubscriptionPath+".tmp",diagSubscriptionPath)}};diagSubMu.Unlock();if e==nil{subMu.Lock();subscription=diagResult(d);subAt=time.Now();subMu.Unlock()};return e}
func currentDiagSubscription()(map[string]any,bool){diagSubMu.Lock();d:=diagSub;diagSubMu.Unlock();if d.CapturedAt==0{return nil,false};boot,sim:=subscriptionIdentity();if d.Boot!=boot||d.SIM==""||sim==""||d.SIM!=sim{return nil,false};return diagResult(d),true}
func loadDiagSubscription(){b,e:=os.ReadFile(diagSubscriptionPath);if e!=nil{return};var d DiagSubscription;if json.Unmarshal(b,&d)!=nil||d.QCI<1||d.QCI>254||d.CapturedAt<=0{return};diagSubMu.Lock();diagSub=d;diagSubMu.Unlock();if v,ok:=currentDiagSubscription();ok{subMu.Lock();subscription=v;subAt=time.Now();subMu.Unlock()}}
func importDiagSubscription(path string)error{f,e:=os.Open(path);if e!=nil{return e};defer f.Close();at:=time.Now().Unix();if st,e:=f.Stat();e==nil{at=st.ModTime().Unix()};scanner:=bufio.NewScanner(io.LimitReader(f,1<<20));scanner.Buffer(make([]byte,4096),65536);var last DiagSubscription;found:=false;for scanner.Scan(){if d,e:=parseDiagSubscriptionLine(scanner.Text());e==nil{last=d;found=true}};if !found{return errors.New("本次采集没有有效 AMBR / QCI")};if e=storeDiagSubscription(last,at);e!=nil{return e};last.CapturedAt=at;out,_:=json.Marshal(diagResult(last));fmt.Println(string(out));return nil}
func startSubscriptionMonitor(){if demo||runtime.GOOS!="linux"{return};loadDiagSubscription();path:="/data/airlink/qos-observer";if e:=os.WriteFile(path+".new",qosObserver,0700);e!=nil{return};if os.Rename(path+".new",path)!=nil{return};go func(){for{command:=exec.Command(path,"0","passive","90");pipe,e:=command.StdoutPipe();if e!=nil{return};if e=command.Start();e!=nil{return};scanner:=bufio.NewScanner(pipe);scanner.Buffer(make([]byte,4096),65536);for scanner.Scan(){if d,e:=parseDiagSubscriptionLine(scanner.Text());e==nil{_ = storeDiagSubscription(d,time.Now().Unix())}};_ = command.Wait();time.Sleep(2*time.Second)}}()}
